+		return nil, fmt.Errorf("build request for %s: %w", rawURL, err)
+	}
+	resp, err := pluginHTTPClient.Do(req)
+	if err != nil {
+		return nil, fmt.Errorf("GET %s: %w", rawURL, err)
+	}
