+	// option, so it stays accepted — `--index /srv/plugin-index` and
+	// bare-path test fixtures keep working. Relative paths and bare names
+	// are still rejected: they'd be ambiguous with plugin names.
+	if isAbsoluteGitPath(u) {
+		return nil
+	}
